Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('815f60b0e9a2fb60f3398df376c419c4404b2add136672580561e6b5291ee3c2',), event=Revised(decision='boxerases', at=datetime(2026, 11, 19, 0, 0, 0), actor='assistant', title="Only the box writes an erasure, on the owner's act or a forget", body="An Erased line is appended by the box alone: when the owner asks through the gated tap, or when a forget takes the copies it caused. No verb of the secretary or the triage agent can write one. A tab's post to the lines admits a rename, an opening, a setup, a person's turn, a stop and an Again, each judged by the lines' rule; every other kind, an erasure among them, is the box's alone, and the rule refuses it for good.", rationale="An injected secretary must not be able to erase the evidence of its own injection. Restated when the tab came to write its own turns (the tab writes its own turns, stage 3 of the local writes): what a tab may post grew, and the erasure stayed the box's.", supersedes=()))